        D("THE_WORLD", "The World", "เดอะเวิลด์", "MAJOR", "Completion brings integration, earned confidence, and readiness for the next cycle.", "Loose ends or incomplete integration are delaying closure and the next beginning.", "ความสำเร็จสมบูรณ์นำมาซึ่งการผสาน ความมั่นใจที่ได้มา และความพร้อมสู่วัฏจักรใหม่", "เรื่องค้างหรือการผสานที่ยังไม่สมบูรณ์กำลังชะลอการปิดฉากและการเริ่มต้นใหม่", "completion|integration|fulfillment", "unfinished business|delay|loose ends", "ความสมบูรณ์|การผสาน|ความเติมเต็ม", "เรื่องค้างคา|ความล่าช้า|สิ่งที่ยังไม่เรียบร้อย"),

        D("ACE_OF_WANDS", "Ace of Wands", "หนึ่งไม้เท้า", "MINOR", "A fresh creative impulse is ready for a concrete first step.", "The spark is blocked by hesitation, poor timing, or energy without direction.", "แรงบันดาลใจใหม่พร้อมเปลี่ยนเป็นก้าวแรกที่เป็นรูปธรรม", "ประกายเริ่มต้นติดขัดเพราะความลังเล จังหวะไม่เหมาะ หรือพลังที่ไร้ทิศทาง", "inspiration|initiative|potential", "blocked energy|hesitation|false start", "แรงบันดาลใจ|การริเริ่ม|ศักยภาพ", "พลังติดขัด|ความลังเล|การเริ่มต้นที่สะดุด"),
        D("TWO_OF_WANDS", "Two of Wands", "สองไม้เท้า", "MINOR", "A larger horizon is visible; planning must now turn possibility into direction.", "Fear of the unknown or weak planning is keeping the future smaller than it needs to be.", "ขอบฟ้าที่กว้างขึ้นปรากฏแล้ว การวางแผนต้องเปลี่ยนความเป็นไปได้ให้เป็นทิศทาง", "ความกลัวสิ่งไม่รู้หรือแผนที่ไม่ชัดกำลังทำให้อนาคตเล็กกว่าที่ควร", "planning|expansion|foresight", "fear of change|poor planning|limited vision", "การวางแผน|การขยายตัว|การมองการณ์ไกล", "กลัวการเปลี่ยนแปลง|แผนไม่ชัด|วิสัยทัศน์จำกัด"),
        D("THREE_OF_WANDS", "Three of Wands", "สามไม้เท้า", "MINOR", "Early effort is producing momentum; look ahead and coordinate the next stage.", "Delays or limited foresight require adjustment before expansion continues.", "ความพยายามช่วงแรกกำลังสร้างแรงส่ง จงมองไกลและประสานขั้นต่อไป", "ความล่าช้าหรือการมองไม่ไกลพอต้องการการปรับก่อนขยายต่อ", "progress|foresight|expansion", "delay|obstacle|limited foresight", "ความก้าวหน้า|การมองการณ์ไกล|การขยาย", "ความล่าช้า|อุปสรรค|การมองไม่ไกล"),
        D("FOUR_OF_WANDS", "Four of Wands", "สี่ไม้เท้า", "MINOR", "A stable milestone deserves recognition, rest, and shared celebration.", "Instability at home or within the group is weakening what should feel secure.", "หมุดหมายที่มั่นคงควรได้รับการยอมรับ การพัก และการเฉลิมฉลองร่วมกัน", "ความไม่มั่นคงในบ้านหรือกลุ่มกำลังทำให้สิ่งที่ควรปลอดภัยอ่อนแรง", "celebration|home|milestone", "instability|conflict at home|unsupported success", "การเฉลิมฉลอง|บ้าน|หมุดหมาย", "ความไม่มั่นคง|ความขัดแย้งในบ้าน|ความสำเร็จที่ขาดแรงหนุน"),
        D("FIVE_OF_WANDS", "Five of Wands", "ห้าไม้เท้า", "MINOR", "Constructive friction can test ideas, sharpen skill, and reveal true priorities.", "Conflict is becoming wasteful, avoided, or driven by competition without purpose.", "แรงเสียดทานที่สร้างสรรค์ช่วยทดสอบความคิด ลับทักษะ และเผยลำดับสำคัญ", "ความขัดแย้งกำลังสูญเปล่า ถูกหลีกเลี่ยง หรือขับเคลื่อนด้วยการแข่งขันที่ไร้เป้าหมาย", "competition|friction|testing", "unresolved conflict|avoidance|wasted energy", "การแข่งขัน|แรงเสียดทาน|การทดสอบ", "ความขัดแย้งค้างคา|การหลีกเลี่ยง|พลังที่สูญเปล่า"),
        D("SIX_OF_WANDS", "Six of Wands", "หกไม้เท้า", "MINOR", "Visible progress and recognition confirm that sustained effort is working.", "Recognition is absent, delayed, or becoming a substitute for inner confidence.", "ความก้าวหน้าที่มองเห็นและการยอมรับยืนยันว่าความพยายามต่อเนื่องกำลังได้ผล", "การยอมรับขาดหาย ล่าช้า หรือกำลังแทนที่ความมั่นใจจากภายใน", "recognition|victory|confidence", "lack of recognition|ego|self-doubt", "การยอมรับ|ชัยชนะ|ความมั่นใจ", "ขาดการยอมรับ|อัตตา|ความไม่มั่นใจ"),
        D("SEVEN_OF_WANDS", "Seven of Wands", "เจ็ดไม้เท้า", "MINOR", "Protecting a worthwhile position requires courage, boundaries, and selective effort.", "Constant defense is creating exhaustion, overwhelm, or surrender before the issue is settled.", "การปกป้องจุดยืนที่มีคุณค่าต้องใช้ความกล้า ขอบเขต และการเลือกใช้พลัง", "การตั้งรับตลอดเวลากำลังสร้างความเหนื่อยล้า ท่วมท้น หรือยอมแพ้ก่อนเรื่องจบ", "defense|conviction|boundaries", "overwhelm|exhaustion|giving up", "การปกป้อง|ความเชื่อมั่น|ขอบเขต", "ความท่วมท้น|ความเหนื่อยล้า|การยอมแพ้"),
        D("EIGHT_OF_WANDS", "Eight of Wands", "แปดไม้เท้า", "MINOR", "Events are moving quickly; clear communication can convert speed into progress.", "Delays, mixed messages, or rushed action are scattering momentum.", "เหตุการณ์กำลังเคลื่อนเร็ว การสื่อสารชัดเจนช่วยเปลี่ยนความเร็วเป็นความก้าวหน้า", "ความล่าช้า ข้อความสับสน หรือการรีบทำกำลังกระจายแรงส่ง", "speed|movement|communication", "delay|mixed messages|haste", "ความรวดเร็ว|การเคลื่อนไหว|การสื่อสาร", "ความล่าช้า|ข้อความสับสน|ความรีบร้อน"),
        D("NINE_OF_WANDS", "Nine of Wands", "เก้าไม้เท้า", "MINOR", "Experience and firm boundaries provide the resilience needed for the final stretch.", "Defensiveness or fatigue is making every demand feel like another threat.", "ประสบการณ์และขอบเขตที่มั่นคงมอบความอดทนสำหรับช่วงสุดท้าย", "การตั้งการ์ดหรือความเหนื่อยล้ากำลังทำให้ทุกความต้องการดูเป็นภัย", "resilience|persistence|boundaries", "fatigue|defensiveness|paranoia", "ความทรหด|ความพากเพียร|ขอบเขต", "ความเหนื่อยล้า|การตั้งการ์ด|ความระแวง"),
        D("TEN_OF_WANDS", "Ten of Wands", "สิบไม้เท้า", "MINOR", "A heavy responsibility is near completion, but the load must be managed consciously.", "Overload calls for delegation, release, or an honest refusal of unnecessary burden.", "ภาระหนักใกล้เสร็จสิ้น แต่ต้องจัดการน้ำหนักอย่างมีสติ", "ภาระเกินกำลังต้องการการมอบหมาย การปล่อย หรือการปฏิเสธสิ่งที่ไม่จำเป็นอย่างซื่อตรง", "responsibility|burden|completion", "overload|delegation|release", "ความรับผิดชอบ|ภาระ|การเสร็จสิ้น", "ภาระเกิน|การมอบหมาย|การปล่อย"),
        D("PAGE_OF_WANDS", "Page of Wands", "เด็กถือไม้เท้า", "MINOR", "Curiosity, news, or a young idea invites experimentation without demanding perfection.", "Scattered enthusiasm or fear of beginning is preventing useful exploration.", "ความอยากรู้ ข่าวสาร หรือความคิดใหม่เชื้อเชิญให้ทดลองโดยไม่ต้องสมบูรณ์แบบ", "ความตื่นเต้นที่กระจัดกระจายหรือกลัวเริ่มต้นกำลังขัดขวางการสำรวจ", "curiosity|discovery|message", "scattered energy|setback|fear of starting", "ความอยากรู้|การค้นพบ|ข่าวสาร", "พลังแตกกระจาย|อุปสรรค|กลัวการเริ่ม"),
        D("KNIGHT_OF_WANDS", "Knight of Wands", "อัศวินไม้เท้า", "MINOR", "Bold movement and confidence can break inertia when paired with a real plan.", "Impulsiveness, frustration, or inconsistent effort is burning energy faster than it creates results.", "การเคลื่อนไหวที่กล้าและความมั่นใจช่วยทำลายความนิ่งเมื่อมีแผนจริงรองรับ", "ความหุนหัน ความหงุดหงิด หรือความพยายามไม่สม่ำเสมอกำลังเผาพลังเร็วกว่าสร้างผล", "bold action|adventure|momentum", "impulsiveness|frustration|inconsistency", "การลงมืออย่างกล้า|การผจญภัย|แรงส่ง", "ความหุนหัน|ความหงุดหงิด|ความไม่สม่ำเสมอ"),
        D("QUEEN_OF_WANDS", "Queen of Wands", "ราชินีไม้เท้า", "MINOR", "Warm confidence and self-directed creativity attract support without chasing approval.", "Insecurity, jealousy, or overextension is dimming an otherwise capable presence.", "ความมั่นใจที่อบอุ่นและความคิดสร้างสรรค์ที่นำตนเองดึงดูดแรงสนับสนุนโดยไม่ต้องไล่ตามการยอมรับ", "ความไม่มั่นใจ ความอิจฉา หรือการทำเกินกำลังกำลังลดแสงของความสามารถ", "confidence|independence|warmth", "insecurity|jealousy|overextension", "ความมั่นใจ|ความเป็นอิสระ|ความอบอุ่น", "ความไม่มั่นใจ|ความอิจฉา|การทำเกินกำลัง"),
        D("KING_OF_WANDS", "King of Wands", "ราชาไม้เท้า", "MINOR", "Visionary leadership turns strong purpose into coordinated, courageous action.", "Leadership is becoming domineering, impulsive, or more attached to vision than execution.", "ภาวะผู้นำที่มีวิสัยทัศน์เปลี่ยนเป้าหมายแรงกล้าเป็นการลงมือที่ประสานและกล้าหาญ", "ภาวะผู้นำกำลังกลายเป็นการครอบงำ หุนหัน หรือยึดภาพฝันมากกว่าการทำจริง", "vision|leadership|enterprise", "domineering|impulsive|unrealistic", "วิสัยทัศน์|ภาวะผู้นำ|การสร้างงาน", "การครอบงำ|ความหุนหัน|ความไม่สมจริง"),

        D("ACE_OF_CUPS", "Ace of Cups", "หนึ่งถ้วย", "MINOR", "An emotional opening offers renewal, affection, and a more honest flow of feeling.", "Feelings are blocked, depleted, or poured outward without enough self-care.", "การเปิดทางอารมณ์นำการฟื้นฟู ความรัก และการไหลของความรู้สึกที่ซื่อตรงขึ้น", "ความรู้สึกติดขัด เหือดแห้ง หรือไหลออกไปโดยขาดการดูแลตนเอง", "emotional opening|love|renewal", "blocked emotion|emptiness|overgiving", "การเปิดใจ|ความรัก|การฟื้นฟู", "อารมณ์ติดขัด|ความว่างเปล่า|การให้เกินพอดี"),
        D("TWO_OF_CUPS", "Two of Cups", "สองถ้วย", "MINOR", "Mutual recognition and balanced exchange create the basis for genuine partnership.", "Unequal effort, disconnection, or unresolved tension is weakening reciprocity.", "การเห็นคุณค่ากันและการแลกเปลี่ยนที่สมดุลสร้างฐานของความร่วมมือที่จริงใจ", "ความพยายามไม่เท่ากัน การตัดขาด หรือความตึงเครียดค้างคากำลังลดการตอบแทนกัน", "partnership|mutuality|connection", "imbalance|separation|tension", "ความร่วมมือ|การตอบแทนกัน|ความเชื่อมโยง", "ความไม่สมดุล|การแยกจาก|ความตึงเครียด"),
        D("THREE_OF_CUPS", "Three of Cups", "สามถ้วย", "MINOR", "Community, friendship, and shared joy restore perspective and belonging.", "Social energy is becoming exclusion, excess, gossip, or a distraction from the real issue.", "ชุมชน มิตรภาพ และความสุขร่วมกันช่วยคืนมุมมองและความรู้สึกเป็นส่วนหนึ่ง", "พลังสังคมกำลังกลายเป็นการกีดกัน ความเกินพอดี การนินทา หรือการหนีเรื่องจริง", "friendship|celebration|community", "exclusion|excess|gossip", "มิตรภาพ|การเฉลิมฉลอง|ชุมชน", "การกีดกัน|ความเกินพอดี|การนินทา"),
        D("FOUR_OF_CUPS", "Four of Cups", "สี่ถ้วย", "MINOR", "Withdrawal creates room to reassess desire, but an overlooked option remains nearby.", "Apathy or self-absorption is making available support difficult to recognize.", "การถอยมาช่วยให้ทบทวนความต้องการ แต่ยังมีทางเลือกที่ถูกมองข้ามอยู่ใกล้ตัว", "ความเฉยชาหรือหมกมุ่นกับตนเองกำลังทำให้มองไม่เห็นแรงสนับสนุนที่มี", "contemplation|reassessment|withdrawal", "apathy|missed opportunity|disconnection", "การใคร่ครวญ|การประเมินใหม่|การถอยออกมา", "ความเฉยชา|พลาดโอกาส|การตัดขาด"),
        D("FIVE_OF_CUPS", "Five of Cups", "ห้าถ้วย", "MINOR", "Grief deserves acknowledgment, while remaining support makes recovery possible.", "Acceptance is beginning, but regret still needs to be integrated rather than denied.", "ความสูญเสียควรได้รับการยอมรับ ขณะที่สิ่งที่ยังเหลือทำให้การฟื้นตัวเป็นไปได้", "การยอมรับกำลังเริ่มขึ้น แต่ความเสียดายยังต้องถูกผสานแทนการปฏิเสธ", "loss|grief|remaining hope", "acceptance|forgiveness|moving on", "ความสูญเสีย|ความเศร้า|ความหวังที่ยังอยู่", "การยอมรับ|การให้อภัย|การเดินต่อ"),
        D("SIX_OF_CUPS", "Six of Cups", "หกถ้วย", "MINOR", "Memory, kindness, or a familiar bond offers emotional context and simple restoration.", "Nostalgia is idealizing the past or preventing a mature response to the present.", "ความทรงจำ ความเมตตา หรือสายสัมพันธ์คุ้นเคยมอบบริบททางใจและการฟื้นฟูที่เรียบง่าย", "ความคิดถึงกำลังแต่งอดีตให้สวยเกินจริงหรือขัดขวางการตอบสนองอย่างเป็นผู้ใหญ่", "nostalgia|kindness|familiarity", "stuck in the past|idealization|immaturity", "ความคิดถึง|ความเมตตา|ความคุ้นเคย", "ติดอยู่ในอดีต|การแต่งอดีต|ความไม่เป็นผู้ใหญ่"),
        D("SEVEN_OF_CUPS", "Seven of Cups", "เจ็ดถ้วย", "MINOR", "Many possibilities are present; values and evidence must separate vision from fantasy.", "Confusion or wishful thinking is easing, making a realistic choice possible.", "มีความเป็นไปได้มากมาย คุณค่าและหลักฐานต้องช่วยแยกวิสัยทัศน์ออกจากภาพฝัน", "ความสับสนหรือการคิดตามใจปรารถนากำลังคลาย ทำให้เลือกอย่างเป็นจริงได้", "choices|imagination|possibility", "clarity|realistic choice|ending confusion", "ทางเลือก|จินตนาการ|ความเป็นไปได้", "ความชัดเจน|ทางเลือกที่เป็นจริง|การสิ้นความสับสน"),
        D("EIGHT_OF_CUPS", "Eight of Cups", "แปดถ้วย", "MINOR", "Walking away from emotional insufficiency creates space for deeper meaning.", "Fear of loss or uncertainty is delaying a departure, or prompting a premature return.", "การเดินออกจากสิ่งที่ไม่เติมเต็มทางใจกำลังเปิดพื้นที่ให้ความหมายที่ลึกกว่า", "ความกลัวการสูญเสียหรือความไม่แน่นอนกำลังชะลอการจากไปหรือทำให้ย้อนกลับเร็วเกิน", "departure|search for meaning|release", "fear of leaving|avoidance|returning", "การจากไป|การค้นหาความหมาย|การปล่อย", "กลัวการจากไป|การหลีกเลี่ยง|การย้อนกลับ"),
        D("NINE_OF_CUPS", "Nine of Cups", "เก้าถ้วย", "MINOR", "A genuine wish or emotional need is being fulfilled; receive it with gratitude and proportion.", "Satisfaction has become excess, complacency, or a wish that does not meet the deeper need.", "ความปรารถนาหรือความต้องการทางใจกำลังได้รับการเติมเต็ม จงรับด้วยความขอบคุณและพอดี", "ความพอใจกำลังกลายเป็นความเกิน ความชะล่าใจ หรือความปรารถนาที่ไม่ตอบโจทย์ลึก", "satisfaction|wish|gratitude", "excess|complacency|unmet deeper need", "ความพอใจ|ความปรารถนา|ความขอบคุณ", "ความเกินพอดี|ความชะล่าใจ|ความต้องการลึกที่ไม่ถูกเติม"),
        D("TEN_OF_CUPS", "Ten of Cups", "สิบถ้วย", "MINOR", "Shared emotional security grows through belonging, aligned values, and durable care.", "Idealized harmony is masking family tension, disconnection, or values that need repair.", "ความมั่นคงทางใจร่วมกันเติบโตจากความเป็นส่วนหนึ่ง คุณค่าที่สอดคล้อง และการดูแลยั่งยืน", "ภาพความสุขสมบูรณ์กำลังปิดบังความตึงเครียดในครอบครัว การตัดขาด หรือคุณค่าที่ต้องซ่อม", "harmony|family|belonging", "disharmony|disconnection|broken ideal", "ความกลมกลืน|ครอบครัว|ความเป็นส่วนหนึ่ง", "ความไม่กลมกลืน|การตัดขาด|ภาพฝันที่แตก"),
        D("PAGE_OF_CUPS", "Page of Cups", "เด็กถือถ้วย", "MINOR", "A tender message, creative feeling, or intuitive surprise deserves curious attention.", "Emotional immaturity, insecurity, or blocked creativity is making a sincere signal hard to trust.", "ข้อความอ่อนโยน ความรู้สึกสร้างสรรค์ หรือสัญญาณจากใจควรได้รับความสนใจอย่างอยากรู้", "ความไม่เป็นผู้ใหญ่ทางอารมณ์ ความไม่มั่นใจ หรือความสร้างสรรค์ติดขัดทำให้เชื่อสัญญาณจริงใจได้ยาก", "emotional message|creativity|intuition", "immaturity|insecurity|creative block", "ข้อความจากใจ|ความสร้างสรรค์|สัญชาตญาณ", "ความไม่เป็นผู้ใหญ่|ความไม่มั่นใจ|ความสร้างสรรค์ติดขัด"),
        D("KNIGHT_OF_CUPS", "Knight of Cups", "อัศวินถ้วย", "MINOR", "A heartfelt offer or imaginative pursuit can move forward when ideals meet action.", "Mood, fantasy, or charm without follow-through is weakening a promising invitation.", "ข้อเสนอจากใจหรือการไล่ตามจินตนาการเดินหน้าได้เมื่ออุดมคติมาพบการลงมือ", "อารมณ์ ภาพฝัน หรือเสน่ห์ที่ไม่ทำต่อกำลังทำให้คำเชิญที่ดีอ่อนแรง", "romance|invitation|imagination", "moodiness|fantasy|empty charm", "ความโรแมนติก|คำเชิญ|จินตนาการ", "อารมณ์แปรปรวน|ภาพฝัน|เสน่ห์ที่ไร้การกระทำ"),
        D("QUEEN_OF_CUPS", "Queen of Cups", "ราชินีถ้วย", "MINOR", "Compassion and emotional intelligence allow deep feeling without losing discernment.", "Sensitivity has become porous boundaries, emotional dependence, or self-neglect.", "ความเมตตาและความฉลาดทางอารมณ์ช่วยให้รู้สึกลึกโดยไม่สูญเสียการพิจารณา", "ความอ่อนไหวกำลังกลายเป็นขอบเขตรั่ว การพึ่งพาทางอารมณ์ หรือการละเลยตนเอง", "compassion|intuition|emotional maturity", "porous boundaries|dependence|self-neglect", "ความเมตตา|สัญชาตญาณ|วุฒิภาวะทางอารมณ์", "ขอบเขตรั่ว|การพึ่งพา|การละเลยตนเอง"),
        D("KING_OF_CUPS", "King of Cups", "ราชาถ้วย", "MINOR", "Emotional steadiness and wise diplomacy can hold complexity without being ruled by it.", "Controlled feeling has become suppression, manipulation, or emotional distance.", "ความมั่นคงทางอารมณ์และการประสานอย่างมีปัญญาช่วยรับความซับซ้อนโดยไม่ถูกมันครอบงำ", "การควบคุมความรู้สึกกำลังกลายเป็นการกดทับ การชักจูง หรือความห่างเหิน", "emotional balance|diplomacy|wisdom", "suppression|manipulation|distance", "สมดุลทางอารมณ์|การประสาน|ปัญญา", "การกดทับ|การชักจูง|ความห่างเหิน"),

        D("ACE_OF_SWORDS", "Ace of Swords", "หนึ่งดาบ", "MINOR", "A clear truth or decisive idea cuts through confusion and enables a clean choice.", "Confusion, misinformation, or a harsh conclusion is weakening sound judgment.", "ความจริงหรือความคิดที่ชัดเจนตัดผ่านความสับสนและเปิดทางให้ตัดสินใจตรงไปตรงมา", "ความสับสน ข้อมูลผิด หรือข้อสรุปที่รุนแรงกำลังทำให้วิจารณญาณอ่อนลง", "clarity|truth|breakthrough", "confusion|misinformation|harshness", "ความชัดเจน|ความจริง|การทะลุผ่าน", "ความสับสน|ข้อมูลผิด|ความรุนแรง"),
        D("TWO_OF_SWORDS", "Two of Swords", "สองดาบ", "MINOR", "A difficult choice needs more honest information and a decision that can no longer be deferred.", "Avoidance is breaking down; overload or exposed truth now forces engagement.", "ทางเลือกที่ยากต้องการข้อมูลที่ซื่อตรงขึ้นและการตัดสินใจที่เลื่อนไม่ได้แล้ว", "การหลีกเลี่ยงกำลังพังลง ข้อมูลล้นหรือความจริงที่เผยออกมาบังคับให้ต้องเผชิญ", "stalemate|choice|boundaries", "indecision|overload|truth exposed", "ทางตัน|ทางเลือก|ขอบเขต", "ความลังเล|ข้อมูลล้น|ความจริงเปิดเผย"),
        D("THREE_OF_SWORDS", "Three of Swords", "สามดาบ", "MINOR", "Painful truth, grief, or separation must be acknowledged before healing can be real.", "Recovery has begun, though resentment or unprocessed pain may still delay release.", "ความจริงที่เจ็บปวด ความเศร้า หรือการแยกจากต้องได้รับการยอมรับก่อนการเยียวยาจะจริง", "การฟื้นตัวเริ่มแล้ว แม้ความขุ่นเคืองหรือความเจ็บที่ยังไม่ผ่านอาจชะลอการปล่อย", "heartbreak|grief|painful truth", "recovery|forgiveness|lingering pain", "หัวใจสลาย|ความเศร้า|ความจริงที่เจ็บปวด", "การฟื้นตัว|การให้อภัย|ความเจ็บที่ค้าง"),
        D("FOUR_OF_SWORDS", "Four of Swords", "สี่ดาบ", "MINOR", "Rest, quiet recovery, and mental distance are necessary before the next action.", "Restlessness, burnout, or returning too soon is preventing genuine restoration.", "การพัก การฟื้นตัวอย่างสงบ และระยะห่างทางความคิดจำเป็นก่อนลงมือครั้งต่อไป", "ความกระสับกระส่าย ภาวะหมดไฟ หรือการกลับเร็วเกินกำลังขัดขวางการฟื้นจริง", "rest|recovery|contemplation", "restlessness|burnout|premature return", "การพัก|การฟื้นตัว|การใคร่ครวญ", "ความกระสับกระส่าย|หมดไฟ|กลับเร็วเกินไป"),
        D("FIVE_OF_SWORDS", "Five of Swords", "ห้าดาบ", "MINOR", "A conflict may be winnable but costly; define what outcome is actually worth pursuing.", "Reconciliation is possible, but resentment or unfinished accountability still needs attention.", "ความขัดแย้งอาจชนะได้แต่มีราคา ควรกำหนดว่าผลลัพธ์ใดคุ้มค่าจริง", "การคืนดีเป็นไปได้ แต่ความขุ่นเคืองหรือความรับผิดชอบที่ยังไม่จบต้องได้รับการดูแล", "conflict|costly victory|self-interest", "reconciliation|resentment|accountability", "ความขัดแย้ง|ชัยชนะราคาแพง|ประโยชน์ตน", "การคืนดี|ความขุ่นเคือง|ความรับผิดชอบ"),
        D("SIX_OF_SWORDS", "Six of Swords", "หกดาบ", "MINOR", "A measured transition carries the situation away from turmoil toward calmer ground.", "Unresolved baggage or resistance is delaying a necessary mental or practical move.", "การเปลี่ยนผ่านอย่างค่อยเป็นค่อยไปกำลังพาสถานการณ์ออกจากความปั่นป่วนสู่พื้นที่สงบขึ้น", "เรื่องค้างหรือการต่อต้านกำลังชะลอการเคลื่อนย้ายทางความคิดหรือทางปฏิบัติที่จำเป็น", "transition|moving on|recovery", "resistance|unfinished baggage|delay", "การเปลี่ยนผ่าน|การเดินต่อ|การฟื้นตัว", "การต่อต้าน|เรื่องค้าง|ความล่าช้า"),
        D("SEVEN_OF_SWORDS", "Seven of Swords", "เจ็ดดาบ", "MINOR", "Strategy and discretion are needed, but the method must remain accountable.", "A concealed issue is being exposed, or self-deception is no longer sustainable.", "ต้องใช้กลยุทธ์และความรอบคอบ แต่วิธีการยังต้องรับผิดชอบและซื่อตรง", "เรื่องที่ซ่อนอยู่กำลังถูกเปิดเผย หรือการหลอกตนเองไม่อาจดำเนินต่อ", "strategy|discretion|independence", "exposure|confession|self-deception", "กลยุทธ์|ความรอบคอบ|ความเป็นอิสระ", "การเปิดโปง|การสารภาพ|การหลอกตนเอง"),
        D("EIGHT_OF_SWORDS", "Eight of Swords", "แปดดาบ", "MINOR", "A restrictive story is limiting perceived options more than the facts themselves.", "New perspective is loosening fear and restoring agency one decision at a time.", "เรื่องเล่าที่จำกัดกำลังทำให้มองเห็นทางเลือกน้อยกว่าข้อเท็จจริง", "มุมมองใหม่กำลังคลายความกลัวและคืนอำนาจในการเลือกทีละการตัดสินใจ", "restriction|fear|limited perspective", "release|new perspective|agency", "ข้อจำกัด|ความกลัว|มุมมองแคบ", "การปลดปล่อย|มุมมองใหม่|อำนาจในการเลือก"),
        D("NINE_OF_SWORDS", "Nine of Swords", "เก้าดาบ", "MINOR", "Anxiety and repeated thought are magnifying pain that needs support, facts, and rest.", "Fear is beginning to ease, though shame or private worry still needs compassionate attention.", "ความกังวลและความคิดซ้ำกำลังขยายความเจ็บที่ต้องการแรงช่วย ข้อเท็จจริง และการพัก", "ความกลัวเริ่มคลาย แม้ความละอายหรือความกังวลส่วนตัวยังต้องได้รับความเมตตา", "anxiety|worry|sleeplessness", "recovery|shame|fear easing", "ความกังวล|ความห่วง|การนอนไม่หลับ", "การฟื้นตัว|ความละอาย|ความกลัวที่คลาย"),
        D("TEN_OF_SWORDS", "Ten of Swords", "สิบดาบ", "MINOR", "A painful cycle has reached its limit; accepting the ending prevents further harm.", "Recovery is possible, but resisting finality may prolong an already completed ending.", "วัฏจักรที่เจ็บปวดมาถึงขีดสุด การยอมรับจุดจบช่วยหยุดความเสียหายเพิ่ม", "การฟื้นตัวเป็นไปได้ แต่การไม่ยอมรับความสิ้นสุดอาจยืดสิ่งที่จบแล้ว", "ending|rock bottom|release", "recovery|resistance to ending|survival", "จุดจบ|จุดต่ำสุด|การปล่อย", "การฟื้นตัว|การต่อต้านจุดจบ|การรอดพ้น"),
        D("PAGE_OF_SWORDS", "Page of Swords", "เด็กถือดาบ", "MINOR", "Curious observation and direct questions can uncover useful information.", "Nervous talk, gossip, or analysis without experience is creating noise instead of clarity.", "การสังเกตอย่างอยากรู้และคำถามตรงช่วยค้นพบข้อมูลที่เป็นประโยชน์", "คำพูดกังวล การนินทา หรือการวิเคราะห์ที่ขาดประสบการณ์กำลังสร้างเสียงรบกวน", "curiosity|vigilance|new information", "gossip|nervousness|poor communication", "ความอยากรู้|ความตื่นตัว|ข้อมูลใหม่", "การนินทา|ความกังวล|การสื่อสารไม่ดี"),
        D("KNIGHT_OF_SWORDS", "Knight of Swords", "อัศวินดาบ", "MINOR", "Focused intellect and decisive movement can address a problem quickly.", "Aggression, haste, or certainty without listening is turning action into avoidable damage.", "ความคิดที่มุ่งมั่นและการเคลื่อนไหวเด็ดขาดช่วยจัดการปัญหาได้รวดเร็ว", "ความก้าวร้าว ความรีบ หรือความมั่นใจโดยไม่ฟังกำลังเปลี่ยนการลงมือเป็นความเสียหายที่เลี่ยงได้", "decisive action|ambition|directness", "aggression|haste|lack of tact", "การลงมือเด็ดขาด|ความทะเยอทะยาน|ความตรง", "ความก้าวร้าว|ความรีบ|ขาดชั้นเชิง"),
        D("QUEEN_OF_SWORDS", "Queen of Swords", "ราชินีดาบ", "MINOR", "Clear boundaries and honest perception support an independent, fair decision.", "Discernment has hardened into bitterness, isolation, or criticism without context.", "ขอบเขตที่ชัดและการมองอย่างซื่อตรงสนับสนุนการตัดสินใจที่อิสระและเป็นธรรม", "การพิจารณากำลังแข็งตัวเป็นความขมขื่น การแยกตัว หรือการวิจารณ์ที่ขาดบริบท", "discernment|independence|boundaries", "bitterness|isolation|harsh criticism", "วิจารณญาณ|ความเป็นอิสระ|ขอบเขต", "ความขมขื่น|การแยกตัว|การวิจารณ์รุนแรง"),
        D("KING_OF_SWORDS", "King of Swords", "ราชาดาบ", "MINOR", "Ethical authority and disciplined reasoning can make a complex decision fair and precise.", "Intellect is being used rigidly, manipulatively, or without regard for human impact.", "อำนาจที่มีจริยธรรมและเหตุผลที่มีวินัยช่วยให้ตัดสินเรื่องซับซ้อนได้อย่างแม่นยำและเป็นธรรม", "สติปัญญากำลังถูกใช้อย่างแข็งทื่อ ชักจูง หรือไม่คำนึงถึงผลต่อผู้คน", "reason|authority|ethical judgment", "rigidity|manipulation|coldness", "เหตุผล|อำนาจ|การตัดสินอย่างมีจริยธรรม", "ความแข็งทื่อ|การชักจูง|ความเย็นชา"),

        D("ACE_OF_PENTACLES", "Ace of Pentacles", "หนึ่งเหรียญ", "MINOR", "A practical opportunity can become stable growth through a grounded first investment.", "A useful opportunity is being delayed, poorly planned, or valued only in the short term.", "โอกาสที่เป็นรูปธรรมสามารถเติบโตอย่างมั่นคงผ่านการลงทุนก้าวแรกที่มีฐาน", "โอกาสที่ดีถูกชะลอ วางแผนไม่ดี หรือถูกมองเพียงผลระยะสั้น", "opportunity|foundation|investment", "missed chance|poor planning|short-term thinking", "โอกาส|รากฐาน|การลงทุน", "พลาดโอกาส|แผนไม่ดี|คิดระยะสั้น"),
        D("TWO_OF_PENTACLES", "Two of Pentacles", "สองเหรียญ", "MINOR", "Flexible prioritization can keep changing demands in workable balance.", "Too many moving parts are producing disorganization, overload, or neglected priorities.", "การจัดลำดับอย่างยืดหยุ่นช่วยให้ความต้องการที่เปลี่ยนไปอยู่ในสมดุลที่จัดการได้", "เรื่องที่เคลื่อนไหวมากเกินกำลังสร้างความไร้ระเบียบ ภาระล้น หรือละเลยสิ่งสำคัญ", "balance|adaptability|priorities", "disorganization|overload|imbalance", "ความสมดุล|การปรับตัว|ลำดับสำคัญ", "ความไร้ระเบียบ|ภาระล้น|ความไม่สมดุล"),
        D("THREE_OF_PENTACLES", "Three of Pentacles", "สามเหรียญ", "MINOR", "Skilled collaboration and clear roles are turning effort into quality work.", "Poor coordination, weak standards, or lack of recognition is limiting shared results.", "ความร่วมมือที่มีทักษะและบทบาทชัดกำลังเปลี่ยนความพยายามเป็นผลงานคุณภาพ", "การประสานไม่ดี มาตรฐานต่ำ หรือขาดการยอมรับกำลังจำกัดผลลัพธ์ร่วม", "teamwork|craft|collaboration", "poor teamwork|low quality|lack of recognition", "การทำงานเป็นทีม|ฝีมือ|ความร่วมมือ", "ทีมไม่ลงตัว|คุณภาพต่ำ|ขาดการยอมรับ"),
        D("FOUR_OF_PENTACLES", "Four of Pentacles", "สี่เหรียญ", "MINOR", "Protecting resources creates security, but healthy stability still allows movement.", "Fear of loss is producing control or hoarding, or a rigid grip is finally beginning to loosen.", "การปกป้องทรัพยากรสร้างความมั่นคง แต่ความมั่นคงที่ดียังยอมให้เกิดการเคลื่อนไหว", "ความกลัวสูญเสียกำลังสร้างการควบคุมหรือกักเก็บ หรือมือที่กำแน่นเริ่มคลาย", "security|conservation|control", "fear of loss|hoarding|release", "ความมั่นคง|การรักษา|การควบคุม", "กลัวสูญเสีย|การกักเก็บ|การปล่อย"),
        D("FIVE_OF_PENTACLES", "Five of Pentacles", "ห้าเหรียญ", "MINOR", "Material or emotional hardship is real, yet support may be closer than isolation suggests.", "Recovery and assistance are emerging; pride or fear must not block access to them.", "ความลำบากทางวัตถุหรือใจเป็นเรื่องจริง แต่ความช่วยเหลืออาจใกล้กว่าที่ความโดดเดี่ยวทำให้เห็น", "การฟื้นตัวและความช่วยเหลือกำลังมา อย่าให้ศักดิ์ศรีหรือความกลัวปิดกั้น", "hardship|exclusion|need for support", "recovery|assistance|ending hardship", "ความลำบาก|การถูกกีดกัน|ต้องการความช่วยเหลือ", "การฟื้นตัว|ความช่วยเหลือ|การสิ้นความลำบาก"),
        D("SIX_OF_PENTACLES", "Six of Pentacles", "หกเหรียญ", "MINOR", "Fair exchange and well-placed generosity create a healthier circulation of resources.", "Giving or receiving carries strings, imbalance, or power that has not been acknowledged.", "การแลกเปลี่ยนที่เป็นธรรมและความเอื้อเฟื้อที่เหมาะสมสร้างการหมุนเวียนทรัพยากรที่ดี", "การให้หรือรับมีเงื่อนไข ความไม่สมดุล หรืออำนาจที่ยังไม่ถูกยอมรับ", "generosity|fair exchange|support", "strings attached|inequality|debt", "ความเอื้อเฟื้อ|การแลกเปลี่ยนเป็นธรรม|การสนับสนุน", "เงื่อนไขแฝง|ความไม่เท่าเทียม|หนี้"),
        D("SEVEN_OF_PENTACLES", "Seven of Pentacles", "เจ็ดเหรียญ", "MINOR", "Patient assessment shows what is growing and where effort should be adjusted.", "Impatience or poor return on effort requires a realistic review of the investment.", "การประเมินอย่างอดทนเผยว่าสิ่งใดกำลังเติบโตและควรปรับแรงตรงไหน", "ความไม่อดทนหรือผลตอบแทนต่ำต้องการการทบทวนการลงทุนอย่างเป็นจริง", "patience|assessment|long-term growth", "impatience|poor return|reassessment", "ความอดทน|การประเมิน|การเติบโตระยะยาว", "ความไม่อดทน|ผลตอบแทนต่ำ|การประเมินใหม่"),
        D("EIGHT_OF_PENTACLES", "Eight of Pentacles", "แปดเหรียญ", "MINOR", "Focused practice and attention to detail are building reliable mastery.", "Repetition without purpose, perfectionism, or low standards is weakening the craft.", "การฝึกอย่างมีสมาธิและใส่ใจรายละเอียดกำลังสร้างความชำนาญที่ไว้ใจได้", "การทำซ้ำไร้เป้าหมาย ความสมบูรณ์แบบเกินไป หรือมาตรฐานต่ำกำลังลดคุณภาพฝีมือ", "practice|skill|diligence", "perfectionism|low quality|empty repetition", "การฝึกฝน|ทักษะ|ความขยัน", "ความสมบูรณ์แบบเกิน|คุณภาพต่ำ|การทำซ้ำไร้เป้าหมาย"),
        D("NINE_OF_PENTACLES", "Nine of Pentacles", "เก้าเหรียญ", "MINOR", "Independent effort has created comfort, competence, and earned self-reliance.", "Dependence, overwork, or measuring worth only by status is undermining real security.", "ความพยายามด้วยตนเองสร้างความสบาย ความสามารถ และการพึ่งตนที่ได้มา", "การพึ่งพา การทำงานเกิน หรือวัดคุณค่าด้วยสถานะเท่านั้นกำลังลดความมั่นคงจริง", "independence|comfort|earned success", "dependence|overwork|status anxiety", "ความเป็นอิสระ|ความสบาย|ความสำเร็จที่สร้างมา", "การพึ่งพา|ทำงานเกิน|กังวลสถานะ"),
        D("TEN_OF_PENTACLES", "Ten of Pentacles", "สิบเหรียญ", "MINOR", "Long-term security grows through shared resources, legacy, and durable agreements.", "Family or financial instability reveals weak foundations, disputed values, or short-term choices.", "ความมั่นคงระยะยาวเติบโตผ่านทรัพยากรร่วม มรดก และข้อตกลงที่ยั่งยืน", "ความไม่มั่นคงในครอบครัวหรือการเงินเผยรากฐานอ่อน คุณค่าที่ขัดกัน หรือทางเลือกระยะสั้น", "legacy|security|shared wealth", "instability|family conflict|weak foundation", "มรดก|ความมั่นคง|ทรัพย์สินร่วม", "ความไม่มั่นคง|ความขัดแย้งครอบครัว|รากฐานอ่อน"),
        D("PAGE_OF_PENTACLES", "Page of Pentacles", "เด็กถือเหรียญ", "MINOR", "A practical study, message, or opportunity rewards careful learning and a realistic plan.", "Procrastination, poor focus, or lack of follow-through is stalling useful progress.", "การเรียน ข่าวสาร หรือโอกาสที่เป็นรูปธรรมให้ผลเมื่อเรียนรู้อย่างรอบคอบและมีแผนจริง", "การผัดวัน สมาธิไม่ดี หรือไม่ทำต่อกำลังหยุดความก้าวหน้าที่เป็นประโยชน์", "study|opportunity|practical plan", "procrastination|poor focus|no follow-through", "การเรียนรู้|โอกาส|แผนที่ปฏิบัติได้", "การผัดวัน|สมาธิไม่ดี|ไม่ทำต่อ"),
        D("KNIGHT_OF_PENTACLES", "Knight of Pentacles", "อัศวินเหรียญ", "MINOR", "Steady routines and dependable effort make slow progress durable.", "Consistency has become stagnation, stubbornness, or work performed without meaning.", "กิจวัตรที่มั่นคงและความพยายามที่ไว้ใจได้ทำให้ความก้าวหน้าช้าแต่ยั่งยืน", "ความสม่ำเสมอกำลังกลายเป็นความหยุดนิ่ง ความดื้อ หรือการทำงานที่ไร้ความหมาย", "reliability|routine|steady progress", "stagnation|stubbornness|meaningless work", "ความไว้ใจได้|กิจวัตร|ความก้าวหน้ามั่นคง", "ความหยุดนิ่ง|ความดื้อ|งานไร้ความหมาย"),
        D("QUEEN_OF_PENTACLES", "Queen of Pentacles", "ราชินีเหรียญ", "MINOR", "Practical care balances material responsibility with embodied well-being.", "Caregiving or work is consuming personal resources, creating insecurity or self-neglect.", "การดูแลที่เป็นรูปธรรมสร้างสมดุลระหว่างความรับผิดชอบทางวัตถุกับสุขภาวะของตน", "การดูแลหรือการงานกำลังกินทรัพยากรส่วนตัว สร้างความไม่มั่นคงหรือละเลยตนเอง", "practical care|security|resourcefulness", "self-neglect|insecurity|work-life imbalance", "การดูแลที่ปฏิบัติได้|ความมั่นคง|การจัดการเก่ง", "การละเลยตนเอง|ความไม่มั่นคง|งานชีวิตไม่สมดุล"),
        D("KING_OF_PENTACLES", "King of Pentacles", "ราชาเหรียญ", "MINOR", "Responsible stewardship turns experience and resources into lasting value.", "Material authority has become greed, rigidity, or status without responsible stewardship.", "การดูแลทรัพยากรอย่างรับผิดชอบเปลี่ยนประสบการณ์และทรัพย์สินเป็นคุณค่าที่ยั่งยืน", "อำนาจทางวัตถุกำลังกลายเป็นความโลภ ความแข็งทื่อ หรือสถานะที่ขาดความรับผิดชอบ", "stewardship|abundance|reliability", "greed|rigidity|status seeking", "การดูแลทรัพยากร|ความอุดมสมบูรณ์|ความไว้ใจได้", "ความโลภ|ความแข็งทื่อ|การไล่ตามสถานะ")
    ];

    private static TarotMeaningDefinition D(
        string id,
        string englishName,
        string thaiName,
        string arcana,
        string englishUpright,
        string englishReversed,
        string thaiUpright,
        string thaiReversed,
        string englishUprightKeywords,
        string englishReversedKeywords,
        string thaiUprightKeywords,
        string thaiReversedKeywords) =>
        D(
            id,
            englishName,
            thaiName,
            arcana,
            ElementFor(id),
            englishUpright,
            englishReversed,
            thaiUpright,
            thaiReversed,
            englishUprightKeywords,
            englishReversedKeywords,
            thaiUprightKeywords,
            thaiReversedKeywords);

    private static TarotMeaningDefinition D(
        string id,
        string englishName,
        string thaiName,
        string arcana,
        string element,
        string englishUpright,
        string englishReversed,
        string thaiUpright,
        string thaiReversed,
        string englishUprightKeywords,
        string englishReversedKeywords,
        string thaiUprightKeywords,
        string thaiReversedKeywords) =>
        new(
            id,
            englishName,
            thaiName,
            arcana,
            element,
            englishUpright,
            englishReversed,
            thaiUpright,
            thaiReversed,
            englishUprightKeywords,
            englishReversedKeywords,
            thaiUprightKeywords,
            thaiReversedKeywords);

    private static string ElementFor(string id)
    {
        if (id.EndsWith("_OF_WANDS", StringComparison.Ordinal)) return "FIRE";
        if (id.EndsWith("_OF_CUPS", StringComparison.Ordinal)) return "WATER";
        if (id.EndsWith("_OF_SWORDS", StringComparison.Ordinal)) return "AIR";
        if (id.EndsWith("_OF_PENTACLES", StringComparison.Ordinal)) return "EARTH";

        return id switch
        {
            "THE_HIGH_PRIESTESS" or "THE_CHARIOT" or "THE_HANGED_MAN" or "DEATH" or "THE_MOON" => "WATER",
            "THE_EMPRESS" or "THE_HIEROPHANT" or "THE_HERMIT" or "THE_DEVIL" or "THE_WORLD" => "EARTH",
            "THE_LOVERS" or "JUSTICE" or "THE_STAR" => "AIR",
            _ => "FIRE"
        };
    }
}
